const tracks = $json;
const results = [];

for (const track of tracks) {
  // Parse the track geometry
  const geom = track.geom;

  // Calculate bounding box
  // This is a simplified version - actual implementation would parse WKB
  const bbox = {
    min_lat: track.min_lat || 0,
    max_lat: track.max_lat || 0,
    min_lng: track.min_lng || 0,
    max_lng: track.max_lng || 0
  };

  // Calculate tiles covered by this track
  const zoomLevels = [0, 1, 2, 3, 4];
  const tiles = [];

  for (const zoom of zoomLevels) {
    const n = Math.pow(2, zoom);
    const minX = Math.floor((bbox.min_lng + 180) / 360 * n);
    const maxX = Math.floor((bbox.max_lng + 180) / 360 * n);
    const minY = Math.floor(
      (1 - Math.log(Math.tan(bbox.max_lat * Math.PI / 180) + 1 / Math.cos(bbox.max_lat * Math.PI / 180)) / Math.PI) / 2 * n
    );
    const maxY = Math.floor(
      (1 - Math.log(Math.tan(bbox.min_lat * Math.PI / 180) + 1 / Math.cos(bbox.min_lat * Math.PI / 180)) / Math.PI) / 2 * n
    );

    for (let x = minX; x <= maxX; x++) {
      for (let y = minY; y <= maxY; y++) {
        tiles.push({
          user_id: track.user_id,
          tile_key: `${zoom}/${x}/${y}`,
          zoom_level: zoom,
          track_id: track.id
        });
      }
    }
  }

  results.push({
    track_id: track.id,
    user_id: track.user_id,
    tiles: tiles,
    point_count: track.point_count,
    distance_meters: track.distance_meters
  });
}

return results;
